  code: [{ t: 'Перебор соответствий (если задача запутанная)', c: R`from itertools import permutations

g = ['АБ', 'АВ', 'БГ', 'ВГ', 'ГД']           # рёбра графа
t = {(1, 2): 12, (1, 4): 7, (2, 3): 9,       # таблица: (i, j): вес, i < j
     (3, 4): 15, (3, 5): 4}
letters = 'АБВГД'
ans = set()
for p in permutations(range(1, 6)):
    m = dict(zip(letters, p))               # буква -> номер в таблице
    ok = all(
        (a + b in g or b + a in g) == ((min(m[a], m[b]), max(m[a], m[b])) in t)
        for i, a in enumerate(letters) for b in letters[i + 1:])
    if ok:
        ans.add(t[tuple(sorted((m['Г'], m['Д'])))])   # длина дороги ГД
print(ans)   # одно значение — ответ однозначен` }],
