/* Часть 3: задания 19–27 */

const GAME_THEORY = R`<p>Позиция — выигрышная (W), если есть ход в проигрышную позицию соперника. Проигрышная (L) — если все ходы ведут в выигрышные позиции соперника. Позиция, где игра уже закончилась, проигрышная для того, кто должен ходить.</p>
<p>Удобно хранить <b>число</b>: <b>+k</b> — ходящий выигрывает за k своих ходов (минимум), <b>−k</b> — ходящий проигрывает, соперник выигрывает самое позднее своим k-м ходом, <b>0</b> — игра окончена. Тогда:</p>
<ul><li><b>19</b>: есть ход Пети в позицию со значением +1 (Ваня выигрывает первым ходом после неудачного хода Пети);</li>
<li><b>20</b>: game(S) == 2 — Петя выигрывает вторым ходом, но не первым;</li>
<li><b>21</b>: game(S) == −2 — Ваня выигрывает первым или вторым ходом, но не гарантированно первым.</li></ul>`;

const GAME_CODE = R`from functools import lru_cache

@lru_cache(None)
def game(s):
    if s >= 66:                    # игра закончена: ходящий проиграл
        return 0
    res = [game(m) for m in (s + 1, s + 4, s * 2)]
    lose = [r for r in res if r <= 0]
    if lose:                       # есть ход в проигрышную для соперника
        return -max(lose) + 1
    return -max(res)               # все ходы ведут к победе соперника

moves = lambda s: (s + 1, s + 4, s * 2)
print('19:', min(s for s in range(1, 66) if any(game(m) == 1 for m in moves(s))))
print('20:', [s for s in range(1, 66) if game(s) == 2])
print('21:', [s for s in range(1, 66) if game(s) == -2])`;

